class EvenSet:
    def __contains__(self, val):
        return val % 2 == 0

print(4 in EvenSet())
print(3 in EvenSet())

class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __repr__(self):
        return f'Point({self.x}, {self.y})'
    def __str__(self):
        return f'({self.x}, {self.y})'

p = Point(1, 2)
print(p)
print(repr(p))

